{
  const pile = "default";
  await RequestJson(baseUrl, "POST", "/api/piles", { pile });
  const model = ResolveOpenAiTestModel(agentManager);
  const created = await RequestJson(baseUrl, "POST", `/api/piles/${pile}/sessions`, {
