    workspaceController.StartResize("explorer", event);
  });
  chatResize.addEventListener("mousedown", function (event) {
    workspaceController.StartResize("chat", event);
  });

  window.addEventListener(
    "pagehide",
    function () {
      session.destroy();
    },
    { once: true }
  );

  return session.destroy;
}

