          (session.updatedAt ? " · " + FormatTimestamp(session.updatedAt) : "");
        button.appendChild(meta);
        button.addEventListener("click", function () {
          NavigateTo({
            screen: "chat",
            pile: route.pile,
            sessionId: session.sessionId,
          });
