.sheaf-file-view-content .sheaf-markdown
{
  padding: 4px 0;
}

.sheaf-chat-workspace
{
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: row;
  overflow: hidden;
  --sheaf-chat-explorer-width: 240px;
  --sheaf-chat-chat-width: 360px;
}

.sheaf-chat-explorer-pane,
.sheaf-chat-chat-pane
{
  flex: 0 0 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--sheaf-chat-surface);
}

.sheaf-chat-explorer-pane
{
  width: var(--sheaf-chat-explorer-width);
  border-right: 1px solid var(--sheaf-chat-border);
}

.sheaf-chat-chat-pane
{
  width: var(--sheaf-chat-chat-width);
  border-left: 1px solid var(--sheaf-chat-border);
}

.sheaf-chat-explorer-pane--collapsed
{
  width: 0;
  min-width: 0;
  border-right: none;
  overflow: hidden;
}

.sheaf-chat-chat-pane--collapsed
{
  width: 0;
  min-width: 0;
  border-left: none;
  overflow: hidden;
}

.sheaf-chat-pane-header
{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--sheaf-chat-border);
  background: var(--sheaf-chat-surface-muted);
  flex-shrink: 0;
}

.sheaf-chat-pane-title
{
  font-size: 12px;
  font-weight: 700;
  color: var(--sheaf-chat-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.sheaf-chat-resize-handle
{
  flex: 0 0 5px;
  cursor: col-resize;
  background: transparent;
  touch-action: none;
}

.sheaf-chat-resize-handle:hover
{
  background: color-mix(in srgb, var(--sheaf-chat-accent) 25%, transparent);
}

.sheaf-chat-file-pane
{
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.sheaf-chat-explorer-tree
{
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 8px 0;
}

