  socket.open();
  socket.receive(
    ServerEnvelope("server.hello", {
      models: [
        { provider: "openai", id: "gpt-4.1", displayName: "GPT 4.1" },
        { provider: "anthropic", id: "claude-sonnet-4", displayName: "Claude Sonnet 4" },
      ],
      activeModel: { provider: "openai", id: "gpt-4.1" },
