            sessionCount: 0,
            latestUpdatedAt: null,
          },
        ];
        return JsonResponse({ pile: body.pile, sessionCount: 0, latestUpdatedAt: null }, true);
      }

      if (path === "/api/piles") {
        return JsonResponse({ piles }, true);
      }

      return JsonResponse({ error: { message: "unexpected request" } }, false);
    },
  });

  await FlushPromises();

