      messageId: "assistant-link",
    }, 3),
  );
  harness.flushAnimationFrames();
  await FlushPromises();

  const assistantLink = harness.app.querySelectorAll(".sheaf-markdown-file-link").find(
    (link) => link.getAttribute("href") === "sheaf-file:docs/readme.md",
  );
  assert.ok(assistantLink, "expected assistant file link");
  assistantLink.click();
  await FlushPromises();

  assert.match(RequiredElement(harness.app, ".sheaf-chat-tab--selected").textContent, /readme\.md/);
});

test("file.changed refetches selected tab and defers stale background tabs", async () =>
{
  const fetchCalls: string[] = [];
  const harness = LoadChatHarness({
    fetch: async (path) => {
      fetchCalls.push(path);
      const response = DefaultFileFetch(path);
      assert.ok(response);
      return response;
    },
  });
  await FlushPromises();

  const readmeButton = RequiredElement(harness.app, ".sheaf-chat-explorer-file");
  readmeButton.click();
  await FlushPromises();

  const otherButton = harness.app.querySelectorAll(".sheaf-chat-explorer-file")[1];
  assert.ok(otherButton);
  otherButton.click();
  await FlushPromises();

  const fileFetchesBefore = fetchCalls.filter((path) => path.includes("/file?")).length;
  assert.equal(fileFetchesBefore, 2);

  const socket = harness.sockets[0];
  socket.receive(
    ServerEnvelope("file.changed", {
      eventType: "fileChanged",
      path: "docs/readme.md",
      fileId: "docs/readme.md",
      changedAt: "2026-06-09T00:00:00.000Z",
      source: "edit_tool",
    }, 10),
  );
  await FlushPromises();

  const readmeTab = harness.app.querySelector(".sheaf-chat-tab");
  assert.ok(readmeTab);
  assert.equal(readmeTab.classList.contains("sheaf-chat-tab--stale"), true);
  assert.equal(
    fetchCalls.filter((path) => path.includes("/file?path=docs%2Freadme.md")).length,
    2,
  );

  readmeTab.click();
  await FlushPromises();

  assert.equal(readmeTab.classList.contains("sheaf-chat-tab--stale"), false);
  assert.equal(
    fetchCalls.filter((path) => path.includes("/file?path=docs%2Freadme.md")).length,
    3,
  );

  socket.receive(
    ServerEnvelope("file.changed", {
      eventType: "fileChanged",
      path: "docs/other.md",
      fileId: "docs/other.md",
      changedAt: "2026-06-09T00:00:01.000Z",
      source: "edit_tool",
    }, 11),
  );
  await FlushPromises();

  assert.equal(
    fetchCalls.filter((path) => path.includes("/file?path=docs%2Fother.md")).length,
    2,
  );
});

