  socket.receive(
    ServerEnvelope("server.hello", {
      models: [],
      activeModel: { provider: "openai", id: "gpt-4.1" },
      historyWindow: {
        oldestSequence: 25,
      },
    }),
  );

  const afterHello = Frames(socket, "client.history_request").length;
